	lda	xix, (xiz-17)	; F0E98A  lda XIX,XIZ+0xef
	ldir85	; F0E98D  ldir
	pop	xix	; F0E98F  pop XIX
	ld	h, (LCD_CurrentLayer:16)	; F0E990  ld H,(0x2540)
	ld	(LCD_CurrentLayer), (Blink_Layer:16)	; F0E994  ld (0x2540),(0x28c8)
	ld	(xix+6), (Blink_SwiFunction)	; F0E99A  ld (XIX+0x06),(0x28c9)
	ldw	(xix+13), (Blink_Op07Word0D)	; F0E99F  ldw (XIX+0x0d),(0x28cc)
	ldw	(xix+15), (Blink_Op07Word0F)	; F0E9A4  ldw (XIX+0x0f),(0x28ce)
	ld	bc, (Blink_BytesPerEntry:16)	; F0E9A9  ld BC,(0x28d0)
	extz	bc	; F0E9AD  extz BC
	ld	(xix+11), bc	; F0E9AF  ld (XIX+0x0b),BC
	cp	(xiz+8), 0x00	; F0E9B2  cp (XIZ+0x08),0x00
	jr	nz, Blink_DrawField_Op07_Skip	; F0E9B6  jr NZ,0xf0e9c0
	lda	xbc, (DLB_BlankField_8:24)	; F0E9B8  lda XBC,0xf78020
	ld	(xix+7), xbc	; F0E9BD  ld (XIX+0x07),XBC
Blink_DrawField_Op07_Skip:
	push	xix	; F0E9C0  push XIX
	call	DisplayListB_RunOne_Stack	; F0E9C1  call 0xf3183d
	ld	(LCD_CurrentLayer:16), h	; F0E9C5  ld (0x2540),H
	pop	xbc	; F0E9C9  pop XBC
	pop	xix	; F0E9CA  pop XIX
	popw	hl	; F0E9CB  pop HL
	unlk XIZ	; F0E9CC  unlk XIZ
