	cp	(0x2820:16), 0x2d	; F0EA7E  cp (0x2820),0x2d
	jr	nz, Blink_CmdArm_SetState_DashTest_Skip2	; F0EA83  jr NZ,0xf0ea8a
Blink_CmdArm_SetState_DashTest_Skip:
